export function applyComicArtworkFit(root=document){
  root.querySelectorAll(".comic-cover img,.comic-release-cover img,.comic-home-cover img,.comic-recommendation-cover img").forEach(img=>{
    const fit=()=>{
      const frame=img.parentElement;
      if(!frame||!img.naturalWidth||!img.naturalHeight)return;
      const sourceRatio=img.naturalWidth/img.naturalHeight;
      const frameRatio=(frame.clientWidth||2)/(frame.clientHeight||3);
      img.classList.toggle("comic-fit-contain",sourceRatio>1.05);
    };
    if(img.complete)fit();else img.addEventListener("load",fit,{once:true});
  });
}

