export function openPreferredComicReader(itemId){
  const item=getState().items[itemId];if(!item?.comicMeta)return{opened:false,reason:"missing_record"};
  const access=readingAccessFor(item),web=sourceUrlFor(item);
  if(access.preferred==="kindle"&&access.kindleOwned)return{opened:launchReader(itemId,"kindle",access.kindleUrl||KINDLE_LIBRARY_URL),service:"kindle"};
  if(web)return{opened:launchReader(itemId,"web",web),service:"web"};
  if(access.kindleOwned)return{opened:launchReader(itemId,"kindle",access.kindleUrl||KINDLE_LIBRARY_URL),service:"kindle"};
  return{opened:false,reason:"missing_source"};
}

async function fetchReaderHandoff(url){
  const response=await fetch("./__vault/reader/handoff",{method:"POST",headers:{"Content-Type":"application/json","X-Vault-Request":"reader-handoff"},body:JSON.stringify({url})});
  if(!response.ok)throw new Error("Reader handoff is unavailable.");return response.json();
}

