export function renderComicsHomeUpdates(state=getState()){
  const eligible=allComics(state).filter(item=>!metaFor(item).hidden&&newCountFor(item)>0&&(item.favorite||metaFor(item).readingStatus==="reading")).sort((a,b)=>newCountFor(b)-newCountFor(a)).slice(0,4);if(!eligible.length)return"";const total=eligible.reduce((sum,item)=>sum+newCountFor(item),0);
  return`<section class="atomic-section comic-home-updates"><div class="atomic-section__head"><div><span class="eyebrow">FAVORITES + ACTIVE READING ONLY</span><h2>${total} NEW COMICS / MANGA ${total===1?"RELEASE":"RELEASES"}</h2></div><button data-route="manga">OPEN RELEASE WATCH</button></div><div class="comic-home-grid">${eligible.map(item=>`<button data-route="manga/${encodeURIComponent(item.id)}">${cover(item,"comic-home-cover")}<span><b>${esc(item.title)}</b><small>${newCountFor(item)} NEW ${unitLabel(metaFor(item))}</small><em>VAULT RECORD →</em></span></button>`).join("")}</div></section>`;
}

async function searchOnline(query){const response=await fetch("./__vault/comics/search",{method:"POST",headers:{"Content-Type":"application/json","X-Vault-Request":"comics-search"},body:JSON.stringify({query})});if(!response.ok)throw new Error(response.status===503?"AI search is unavailable. You can still add this series manually.":`Search returned ${response.status}.`);return response.json()}
const normalizedComicTitle=value=>String(value||"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
const COMIC_METADATA_REFRESH_MS=7*24*60*60*1000;
const comicMetadataSignature=item=>JSON.stringify([normalizedComicTitle(item.title),normalizedComicTitle(item.creator),normalizedComicTitle(item.publisher),String(item.year||""),String(metaFor(item).format||""),String(metaFor(item).sourceLedger?.externalId||"")]);
export async function correctAllComicMetadata({onProgress=()=>{},force=false,control=null}={}){
  const all=allComics(),ledger=getState().metadata.comicsManga?.metadataRefresh?.items||{},now=Date.now(),records=all.filter(item=>{if(metaFor(item).metadataAuthority?.manualFields?.length)return false;const prior=ledger[item.id];return force||!prior||prior.status!=="updated"||prior.signature!==comicMetadataSignature(item)||now-Date.parse(prior.checkedAt||0)>=COMIC_METADATA_REFRESH_MS}),results=[];
  for(let index=0;index<records.length;index++){
    await (control||globalThis.__vaultActiveJobControl)?.checkpoint?.();
    const item=getState().items[records[index].id];if(!item?.comicMeta)continue;
    let status="failed",reason="No confident exact match";
    try{
      const query=[item.title,item.creator,item.publisher,item.year].filter(Boolean).join(" "),payload=await searchOnline(query),candidates=payload.candidates||[],wanted=normalizedComicTitle(item.title),exact=candidates.find(candidate=>normalizedComicTitle(candidate.title)===wanted||(candidate.alternateTitles||[]).some(title=>normalizedComicTitle(title)===wanted)),candidate=exact;
      if(candidate){
        update(save=>{const target=save.items[item.id],meta=target?.comicMeta;if(!target||!meta)return;const correctedAt=new Date().toISOString();target.title=String(candidate.title||target.title).trim();target.creator=String(candidate.creator||target.creator||"").trim();target.publisher=String(candidate.publisher||target.publisher||"").trim();target.year=Number(candidate.startYear||target.year||0)||null;if((candidate.genres||[]).length)target.genres=[...new Set([(candidate.format||meta.format)==="manga"?"Manga":"Comics",...candidate.genres])].slice(0,8);target.description=String(candidate.description||target.description||"").trim();meta.format=COMIC_FORMATS.has?.(candidate.format)?candidate.format:(candidate.format||meta.format);if(PUBLICATION.has(candidate.publicationStatus))meta.publicationStatus=candidate.publicationStatus;if(candidate.unitType)meta.progressUnit=candidate.unitType;if(candidate.releaseLane&&LANES.has(candidate.releaseLane))meta.releaseLane=candidate.releaseLane;if(Number(candidate.totalUnits)>0)meta.latestKnown=Math.max(Number(meta.readThrough||0),Number(candidate.totalUnits));meta.alternateTitles=(candidate.alternateTitles||[]).slice(0,6);meta.metadataCorrectedAt=correctedAt;meta.metadataConfidence=exact?"exact_title":"best_available";meta.sourceLedger||={};if(candidate.sourceUrl)meta.sourceLedger.primary={name:candidate.sourceName||"Verified catalog source",url:safeUrl(candidate.sourceUrl),checkedAt:correctedAt};if(candidate.officialUrl)meta.sourceLedger.officialUrl=safeUrl(candidate.officialUrl);if(candidate.externalId)meta.sourceLedger.externalId=String(candidate.externalId)});
        status="updated";reason=exact?"Exact title verified":"Best catalog match applied";
      }else if(candidates.length){update(save=>{save.metadata.comicsManga||={};const queue=save.metadata.comicsManga.metadataReview||=[];const prior=queue.find(entry=>entry.itemId===item.id&&entry.status==="pending"),record={itemId:item.id,title:item.title,status:"pending",candidates:candidates.slice(0,5).map(candidate=>({...candidate,coverImageUrl:"",remoteCoverImageUrl:""})),createdAt:new Date().toISOString()};if(prior)Object.assign(prior,record);else queue.push(record);save.metadata.comicsManga.metadataReview=queue});status="review";reason="Choose the exact series match"}
    }catch(error){reason=error.message||reason}
    results.push({itemId:item.id,title:item.title,status,reason});update(save=>{save.metadata.comicsManga||={};save.metadata.comicsManga.metadataRefresh||={items:{}};save.metadata.comicsManga.metadataRefresh.items||={};const current=save.items[item.id];save.metadata.comicsManga.metadataRefresh.items[item.id]={signature:comicMetadataSignature(current||item),checkedAt:new Date().toISOString(),status,message:reason}});onProgress({processed:index+1,total:records.length,libraryTotal:all.length,skipped:all.length-records.length,updated:results.filter(entry=>entry.status==="updated").length,failed:results.filter(entry=>entry.status!=="updated").length,title:item.title});
  }
  const completedAt=new Date().toISOString(),skipped=all.length-records.length;update(save=>{save.metadata.comicsManga||={};save.metadata.comicsManga.metadataRepair={completedAt,total:records.length,libraryTotal:all.length,skipped,updated:results.filter(entry=>entry.status==="updated").length,failed:results.filter(entry=>entry.status!=="updated").length,results};save.metadata.comicsManga.metadataRefresh||={items:{}};save.metadata.comicsManga.metadataRefresh.completedAt=completedAt});
  return{total:records.length,libraryTotal:all.length,skipped,updated:results.filter(entry=>entry.status==="updated").length,failed:results.filter(entry=>entry.status!=="updated").length,results,completedAt};
}

export function pendingComicMetadataReviews(){return(getState().metadata?.comicsManga?.metadataReview||[]).filter(entry=>entry.status==="pending")}
