export function openComicAddDialog(onAdded=()=>{}){
  const state=getState();openModal({title:"ADD COMICS / MANGA SERIES",body:`<div class="comic-add-dialog"><p>Search by title, alternate title, creator, publisher, or year. Suggestions begin after three characters; you confirm the exact record before it enters the Vault.</p><div class="comic-search-box"><input type="search" data-comic-search-query autocomplete="off" placeholder="START TYPING A SERIES TITLE"><button class="button primary" data-comic-search>SEARCH</button></div><div class="comic-search-status" data-comic-search-status>READY FOR A TITLE</div><div class="comic-search-results" data-comic-search-results></div><button class="button" data-comic-manual>ADD MANUALLY</button></div>`});
  const root=document.querySelector("#modal-root"),input=root.querySelector("[data-comic-search-query]"),results=root.querySelector("[data-comic-search-results]"),status=root.querySelector("[data-comic-search-status]");let candidates=[];
  const run=async()=>{const query=input.value.trim();if(query.length<3){status.textContent="TYPE AT LEAST THREE CHARACTERS";return}const local=allComics(state).filter(item=>item.title.toLowerCase().includes(query.toLowerCase())).slice(0,4);status.textContent="AI IS CHECKING TITLES, RUNS, CREATORS, AND RELEASE SOURCES…";results.innerHTML=local.map(item=>`<button class="comic-local-match" data-comic-existing="${esc(item.id)}"><b>${esc(item.title)}</b><span>ALREADY IN YOUR VAULT</span><strong>OPEN →</strong></button>`).join("");try{const response=await searchOnline(query);candidates=response.candidates||[];results.insertAdjacentHTML("beforeend",candidates.map(resultCard).join("")||`<div class="empty"><b>NO ONLINE MATCHES.</b>Try another title or add it manually.</div>`);status.textContent=`${candidates.length} ONLINE MATCH${candidates.length===1?"":"ES"} · CONFIRM BEFORE ADDING`}catch(error){status.textContent=error.message}};
  root.querySelector("[data-comic-search]").onclick=run;input.oninput=()=>{clearTimeout(searchTimer);if(input.value.trim().length>=3)searchTimer=setTimeout(run,700)};root.querySelector("[data-comic-manual]").onclick=()=>openManualComicDialog(onAdded);
  results.onclick=async event=>{const existing=event.target.closest("[data-comic-existing]")?.dataset.comicExisting;if(existing){closeModal();location.hash=`#/manga/${encodeURIComponent(existing)}`;return}const index=event.target.closest("[data-comic-candidate]")?.dataset.comicCandidate;if(index!=null&&candidates[index]){status.textContent="PREPARING METADATA AND A RECOGNIZABLE PUBLISHED COVER…";const prepared=await prepareCandidateForReview(candidates[index]);openCandidateConfirmDialog(prepared,onAdded)}};
}

async function prepareCandidateForReview(candidate){
  if(artworkUrl(candidate.coverImageUrl))return candidate;
  try{
    const probe={id:createId("comic_preview"),title:candidate.title,creator:candidate.creator||"",type:candidate.format||"manga",comicMeta:{format:candidate.format||"manga"}},payload=await discoverComicArtwork([probe]),result=(payload.results||[]).find(entry=>entry.itemId===probe.id&&entry.confidence!=="low");
    if(result?.imageUrl)return{...candidate,coverImageUrl:result.imageUrl,coverSourceUrl:result.pageUrl,coverSourceName:result.sourceName};
  }catch{}
  return candidate;
}

function candidateForm(candidate,manual=false){
  const format=FORMATS.has(candidate.format)?candidate.format:"manga",defaultUnit=format==="manga"?"chapters":format==="graphic_novel"?"simple":"issues",defaultLane=format==="manga"?"official_english_chapters":format==="graphic_novel"?"collected_editions":"comic_issues";
  const genres=(candidate.genres||[]).join(" · "),coverSource=safeUrl(candidate.coverSourceUrl),hasCover=Boolean(artworkUrl(candidate.coverImageUrl));
  return`<div class="comic-confirm-form">${manual?`<label>TITLE<input data-confirm-title value="${esc(candidate.title||"")}" required></label><label>CREATOR<input data-confirm-creator value="${esc(candidate.creator||"")}"></label>`:`<div class="comic-match-summary">${candidateCover(candidate,"comic-confirm-cover")}<div><span class="eyebrow">SEARCH MATCH // YOUR CONFIRMATION REQUIRED</span><h3>${esc(candidate.title)}</h3><p>${esc(candidate.creator||"Creator unknown")}${candidate.publisher?` · ${esc(candidate.publisher)}`:""}${candidate.startYear?` · ${candidate.startYear}`:""}</p>${genres?`<small>${esc(genres)}</small>`:""}<small>${esc(candidate.description||candidate.matchReason||"Review this record before adding it.")}</small><em>${hasCover?`PUBLISHED COVER · ${esc(candidate.coverSourceName||"VERIFIED SOURCE")}`:"NO CONFIDENT PUBLISHED COVER FOUND — TRY ANOTHER MATCH"}</em>${coverSource?`<a href="${esc(coverSource)}" target="_blank" rel="noreferrer">VIEW ARTWORK SOURCE</a>`:""}</div></div>`}<div class="comic-field-grid"><label>FORMAT<select data-confirm-format>${[["manga","MANGA"],["comic","COMIC"],["graphic_novel","GRAPHIC NOVEL"],["webcomic","WEBCOMIC"]].map(([value,label])=>`<option value="${value}" ${format===value?"selected":""}>${label}</option>`).join("")}</select></label><label>YOUR STATUS<select data-confirm-status>${["planned","reading","cooking","paused","completed","dropped"].map(value=>`<option value="${value}">${statusLabel(value)}</option>`).join("")}</select></label><label>PROGRESS UNIT<select data-confirm-unit>${["chapters","issues","volumes","editions","simple"].map(value=>`<option value="${value}" ${defaultUnit===value?"selected":""}>${value.toUpperCase()}</option>`).join("")}</select></label><label>READ THROUGH<input type="number" min="0" step="0.1" value="0" data-confirm-read></label><label>LATEST KNOWN<input type="number" min="0" step="0.1" value="${Number(candidate.totalUnits||0)}" data-confirm-latest></label><label>PUBLICATION<select data-confirm-publication>${["ongoing","hiatus","complete","cancelled","unknown"].map(value=>`<option value="${value}" ${(candidate.publicationStatus||"unknown")===value?"selected":""}>${publicationLabel(value)}</option>`).join("")}</select></label><label>RELEASE LANE<select data-confirm-lane>${[...LANES].map(value=>`<option value="${value}" ${defaultLane===value?"selected":""}>${laneLabel(value)}</option>`).join("")}</select></label></div>${!manual?`<label class="comic-check-label"><input type="checkbox" data-confirm-cover ${hasCover?"checked":""} ${hasCover?"":"disabled"}> ${hasCover?"USE THIS PUBLISHED COVER":"PUBLISHED COVER REQUIRED BEFORE SAVING"}</label>`:""}<label class="comic-check-label"><input type="checkbox" data-confirm-monitor checked> MONITOR FOR NEW RELEASES</label><label class="comic-check-label"><input type="checkbox" data-confirm-favorite> FAVORITE</label></div>`;
}
function openCandidateConfirmDialog(candidate,onAdded){openModal({title:"CONFIRM SERIES MATCH",body:candidateForm(candidate),actions:[{label:"ADD TO VAULT",primary:true,handler:async dialog=>{const useCover=Boolean(dialog.querySelector("[data-confirm-cover]")?.checked);if(!useCover)return toast("PUBLISHED COVER REQUIRED","Choose a result with recognizable artwork before saving.");const id=addConfirmedComic(candidate,dialog);closeModal();toast("SERIES ADDED","Saving the selected published cover…");await attachComicArtwork(id,{...candidate,allowGenerated:false});onAdded(id)}}]})}
function openManualComicDialog(onAdded){const candidate={title:"",creator:"",format:"manga",publicationStatus:"unknown",sourceName:"Manual record",sourceUrl:"",officialUrl:""};openModal({title:"ADD SERIES MANUALLY",body:candidateForm(candidate,true),actions:[{label:"FIND DETAILS + COVER",primary:true,handler:async dialog=>{const title=dialog.querySelector("[data-confirm-title]").value.trim();if(!title){toast("TITLE REQUIRED","Enter a series title before searching.");return}candidate.title=title;candidate.creator=dialog.querySelector("[data-confirm-creator]").value.trim();toast("SEARCHING SERIES","Finding a recognizable published cover before saving…");const prepared=await prepareCandidateForReview(candidate);if(!artworkUrl(prepared.coverImageUrl))return toast("NO PUBLISHED COVER FOUND","Try the normal title search or a more specific title.");closeModal();openCandidateConfirmDialog(prepared,onAdded)}}]})}
function addConfirmedComic(candidate,dialog){
  const format=dialog.querySelector("[data-confirm-format]").value,readingStatus=dialog.querySelector("[data-confirm-status]").value,progressUnit=dialog.querySelector("[data-confirm-unit]").value,readThrough=Math.max(0,Number(dialog.querySelector("[data-confirm-read]").value)||0),latestKnown=Math.max(readThrough,Number(dialog.querySelector("[data-confirm-latest]").value)||0),publicationStatus=dialog.querySelector("[data-confirm-publication]").value,releaseLane=dialog.querySelector("[data-confirm-lane]").value,monitoring=dialog.querySelector("[data-confirm-monitor]").checked,favorite=dialog.querySelector("[data-confirm-favorite]").checked,id=createId(format==="manga"?"manga":"comic"),addedAt=new Date().toISOString();
  update(save=>{save.items[id]={id,type:format==="manga"?"manga":"comic",wing:"manga",title:String(candidate.title).trim(),creator:String(candidate.creator||"").trim(),publisher:String(candidate.publisher||"").trim(),year:Number(candidate.startYear||0)||null,genres:[...new Set([format==="manga"?"Manga":"Comics",...(candidate.genres||[])])].slice(0,8),description:String(candidate.description||"").trim(),status:itemStatus(readingStatus),owned:false,favorite,addedAt,comicMeta:{format,readingStatus,publicationStatus,progressUnit,readThrough,latestKnown,releaseLane,monitoring,hidden:false,releases:[],sourceLedger:{primary:candidate.sourceUrl?{name:candidate.sourceName||"Online match",url:safeUrl(candidate.sourceUrl),checkedAt:addedAt}:null,officialUrl:safeUrl(candidate.officialUrl),externalId:String(candidate.externalId||"")},readingAccess:{kindleOwned:false,kindleUrl:"",webUrl:safeUrl(candidate.officialUrl||candidate.sourceUrl),preferred:"auto"},addedBy:candidate.sourceUrl?"ai_confirmed_search":"manual",importedAt:addedAt}}});
  ensureComicsMangaV2();emit("COMIC_SERIES_ADDED",{itemId:id,wing:"manga",meta:{title:candidate.title,format}});return id;
}

export async function attachComicArtwork(itemId,source={}){
  const item=getState().items[itemId];if(!item?.comicMeta)return{saved:false,error:"missing_record"};
  const localCandidate=artworkUrl(source.coverImageUrl||source.imageUrl);
  if(localCandidate.startsWith("./assets/artwork/")&&source.requireApproval){const approvalId=queueArtworkApproval({kind:"comic",itemId,target:"main",key:`comic:${itemId}:main`,title:item.title,subtitle:"Published cover candidate",path:localCandidate,sourceName:source.coverSourceName||source.sourceName||"Published cover",sourceUrl:safeUrl(source.coverSourceUrl||source.sourceUrl)});return{saved:Boolean(approvalId),queued:Boolean(approvalId),path:localCandidate,kind:"published"}}
  if(localCandidate.startsWith("./assets/artwork/")){const savedAt=new Date().toISOString();update(save=>{const record=save.items[itemId];if(!record?.comicMeta)return;record.artwork=localCandidate;record.comicMeta.artworkCredit=source.coverSourceName||source.sourceName||"Published cover";record.comicMeta.artworkKind="published";record.comicMeta.artworkPolicyVersion=3;record.comicMeta.artworkAddedAt=savedAt});return{saved:true,path:localCandidate,kind:"published"}}
  let imageUrl=safeUrl(source.coverImageUrl||source.imageUrl),pageUrl=safeUrl(source.coverSourceUrl||source.pageUrl||source.officialUrl||source.sourceUrl||item.comicMeta.sourceLedger?.officialUrl||item.comicMeta.sourceLedger?.primary?.url),artSource=source;
  const saveResult=(payload,credit,kind,url="")=>{if(source.requireApproval){const approvalId=queueArtworkApproval({kind:"comic",itemId,target:"main",key:`comic:${itemId}:main`,title:item.title,subtitle:"Published cover candidate",path:payload.path,sourceName:credit,sourceUrl:safeUrl(url)});return{saved:Boolean(approvalId),queued:Boolean(approvalId),path:payload.path,kind}}const savedAt=new Date().toISOString();update(save=>{const record=save.items[itemId];if(!record?.comicMeta)return;record.artwork=payload.path;record.comicMeta.artworkCredit=credit;record.comicMeta.artworkKind=kind;record.comicMeta.artworkPolicyVersion=3;record.comicMeta.artworkAddedAt=savedAt;record.comicMeta.sourceLedger||={};record.comicMeta.sourceLedger.artwork={name:credit,url:safeUrl(url),imageUrl:safeUrl(payload.sourceUrl),checkedAt:savedAt,kind}});emit("COMIC_ARTWORK_ADDED",{itemId,wing:"manga",meta:{title:item.title,source:credit,kind}});return{saved:true,path:payload.path,kind}};
  const tryPublished=async()=>{if(!imageUrl&&!pageUrl)return null;
    try{
      const response=await fetch("./__vault/comics/artwork/download",{method:"POST",headers:{"Content-Type":"application/json","X-Vault-Request":"comics-artwork-download"},body:JSON.stringify({itemId,imageUrl,pageUrl})});
      if(response.ok){const payload=await response.json(),credit=String(artSource.coverSourceName||artSource.sourceName||"Published cover source");return saveResult(payload,credit,"published",artSource.coverSourceUrl||artSource.pageUrl||artSource.officialUrl||artSource.sourceUrl||payload.sourceUrl)}
    }catch{}return null;
  };
  const direct=await tryPublished();if(direct)return direct;
  if(!source.discoveryComplete){try{const payload=await discoverComicArtwork([item]),result=(payload.results||[]).find(entry=>entry.itemId===itemId&&entry.confidence!=="low");if(result){artSource={...result,coverImageUrl:result.imageUrl,coverSourceUrl:result.pageUrl,coverSourceName:result.sourceName,discoveryComplete:true};imageUrl=safeUrl(result.imageUrl);pageUrl=safeUrl(result.pageUrl);const discovered=await tryPublished();if(discovered)return discovered}}catch{}
  }
  if(source.allowGenerated!==true)return{saved:false,error:"no_familiar_cover"};
  try{
    const response=await fetch("./__vault/comics/artwork/generate",{method:"POST",headers:{"Content-Type":"application/json","X-Vault-Request":"comics-artwork-generate"},body:JSON.stringify({itemId,title:item.title,creator:item.creator||"",format:metaFor(item).format||item.type||"manga"})});
    if(!response.ok)return{saved:false,error:"artwork_generation_unavailable"};
    const payload=await response.json(),credit=String(payload.credit||"Vault-generated archive cover");return saveResult(payload,credit,payload.kind||"vault_generated");
  }catch{return{saved:false,error:"artwork_service_unavailable"}}
}

export async function replaceComicArtwork(itemId){
  const item=getState().items[itemId];if(!item?.comicMeta)return{saved:false,error:"missing_record"};
  return attachComicArtwork(itemId,{allowGenerated:false,requireApproval:true});
}

export async function replaceLegacyGeneratedComicArtwork(){
  const generated=item=>{const meta=metaFor(item),kind=String(meta.artworkKind||meta.sourceLedger?.artwork?.kind||"").toLowerCase(),credit=String(meta.artworkCredit||meta.sourceLedger?.artwork?.name||"").toLowerCase();return["ai_generated","vault_generated"].includes(kind)||/\b(ai|vault)[ -]?generated\b/.test(credit)};
  const targets=allComics().filter(item=>generated(item)&&!metaFor(item).artworkOverride);let saved=0,failed=0;
  for(const item of targets){const result=await replaceComicArtwork(item.id);if(result.saved)saved++;else{failed++;update(save=>{if(save.items[item.id]?.comicMeta)save.items[item.id].comicMeta.legacyReplacementLastAttempt=new Date().toISOString()})}}
  return{total:targets.length,saved,failed};
}

async function discoverComicArtwork(series){
  const response=await fetch("./__vault/comics/artwork/discover",{method:"POST",headers:{"Content-Type":"application/json","X-Vault-Request":"comics-artwork-discover"},body:JSON.stringify({series:series.map(item=>({itemId:item.id,title:item.title,creator:item.creator||"",format:metaFor(item).format||item.type||"manga"}))})});
  if(!response.ok)throw new Error(response.status===429?"AI artwork search is busy. Try again in a moment.":"AI artwork discovery is unavailable.");return response.json();
}

export function autoFillComicArtwork({onProgress=()=>{},control=null}={}){
  if(artworkBackfillPromise)return artworkBackfillPromise;
  artworkBackfillPromise=(async()=>{
    const missing=allComics().filter(item=>!artFor(item)),total=missing.length;let processed=0,saved=0,failed=0;
    for(let index=0;index<missing.length;index+=8){
      await (control||globalThis.__vaultActiveJobControl)?.checkpoint?.();
      const batch=missing.slice(index,index+8);let payload={results:[]};try{payload=await discoverComicArtwork(batch)}catch{}
      const byId=new Map((payload.results||[]).map(result=>[result.itemId,result]));
      for(const item of batch){const result=byId.get(item.id),source=result&&result.confidence!=="low"?{...result,coverImageUrl:result.imageUrl,coverSourceUrl:result.pageUrl,coverSourceName:result.sourceName,requireApproval:true}:{requireApproval:true};const outcome=await attachComicArtwork(item.id,source);outcome.saved?saved++:failed++;processed++;onProgress({processed,total,saved,failed})}
    }
    return{processed,total,saved,failed,remaining:allComics().filter(item=>!artFor(item)).length};
  })().finally(()=>{artworkBackfillPromise=null});
  return artworkBackfillPromise;
}

export async function checkComicReleases({force=false}={}){
  if(releaseCheckPromise)return releaseCheckPromise;
  const state=getState(),stage=state.metadata.comicsManga||{},last=Date.parse(stage.lastCheckedAt||0);
  if(!force&&last&&Date.now()-last<6*60*60*1000)return{skipped:true,changed:[]};
  const monitored=allComics(state).filter(item=>comicMonitoringEligible(item)&&!metaFor(item).hidden).slice(0,24);
  if(!monitored.length)return{skipped:true,changed:[]};
  releaseCheckPromise=(async()=>{
    try{
      const response=await fetch("./__vault/comics/releases",{method:"POST",headers:{"Content-Type":"application/json","X-Vault-Request":"comics-releases"},body:JSON.stringify({series:monitored.map(item=>({itemId:item.id,title:item.title,creator:item.creator||"",releaseLane:metaFor(item).releaseLane,latestKnown:Number(metaFor(item).latestKnown||0)}))})});
      if(!response.ok)throw new Error(`Release service returned ${response.status}.`);
      const payload=await response.json(),checkedAt=payload.checkedAt||new Date().toISOString(),changed=[];
      update(save=>{
        for(const result of payload.results||[]){const item=save.items[result.itemId],meta=item?.comicMeta;if(!meta)continue;const latest=Math.max(Number(meta.latestKnown||0),Number(result.latestNumber||0));if(latest>Number(meta.latestKnown||0)){meta.latestKnown=latest;changed.push({itemId:item.id,title:item.title,latest})}if(PUBLICATION.has(result.publicationStatus))meta.publicationStatus=result.publicationStatus;meta.lastCheckedAt=checkedAt;meta.lastReleaseLabel=String(result.latestLabel||"");if(result.sourceUrl)meta.sourceLedger.primary={name:String(result.sourceName||"Verified online source"),url:safeUrl(result.sourceUrl),checkedAt};if(result.officialUrl)meta.sourceLedger.officialUrl=safeUrl(result.officialUrl)}
        save.metadata.comicsManga.lastCheckedAt=checkedAt;save.metadata.comicsManga.lastCheckStatus="complete";
      });
      changed.forEach(entry=>emit("COMIC_RELEASE_FOUND",{itemId:entry.itemId,wing:"manga",meta:{title:entry.title,latest:entry.latest}}));return{checked:monitored.length,changed};
    }catch(error){update(save=>{save.metadata.comicsManga.lastCheckStatus="unavailable"});throw error}finally{releaseCheckPromise=null}
  })();return releaseCheckPromise;
}
